  'Com isAxisInversed, ângulos customizados e animate: false.': <String>['With isAxisInversed, custom angles, and animate: false.', 'Com isAxisInversed, ângulos personalizados e animate: false.', 'Con isAxisInversed, ángulos personalizados y animate: false.', 'Avec isAxisInversed, angles personnalisés et animate : false.'],
